function challengeChampion(c,ch,ms,fields,entrySet=null,progress='',completed=false){
 const skins=D.skins.filter(x=>x.championId===ch.id&&x.isTFT!==true),chromas=D.chromas.filter(x=>x.championId===ch.id&&x.isTFT!==true),selected=(list,i)=>!list.length||list.map(Number).includes(Number(i));
 const allowed=(x,q)=>!entrySet||entrySet.has(`${x.id}:${q??'base'}`);
 const visible=skins.filter(x=>selected(c.skins,x.id)&&(!c.chromas.length||chromas.some(q=>q.skinId===x.id&&selected(c.chromas,q.id)))||ms.some(m=>Number(m.skinId)===x.id)).filter(x=>!entrySet||[...entrySet].some(k=>k.startsWith(`${x.id}:`)));
 const matched=new Set();
 const row=(label,rows,kind,img)=>{const a=stats(rows);return `<tr class="ct-${kind}"><th scope="row"><span class="ct-name">${img?`<img loading="lazy" src="${esc(img)}" alt="">`:''}${esc(label)}</span></th>${fields.map(k=>`<td>${esc(display(k,a[k]))}</td>`).join('')}</tr>${challengeEternals(rows,c)?`<tr class="ct-eternals"><td colspan="${fields.length+1}">${challengeEternals(rows,c)}</td></tr>`:''}`};
 const skinRows=visible.map(x=>{const sm=ms.filter(m=>m.skinId!=null&&Number(m.skinId)===x.id);sm.forEach(m=>matched.add(m));const qs=c.includeChromas===false?[]:chromas.filter(q=>q.skinId===x.id&&allowed(x,q.id)&&(selected(c.chromas,q.id)||sm.some(m=>Number(m.chromaId)===q.id)));const used=new Set();const cr=qs.map(q=>{const qm=sm.filter(m=>m.chromaId!=null&&Number(m.chromaId)===q.id);qm.forEach(m=>used.add(m));return row(chromaLabel(q,x),qm,'chroma','')}).join('');const other=sm.filter(m=>!used.has(m));return (c.includeSkins===false?'':row(skinLabel(x,ch),sm,'skin',skinPortrait(ch,x)))+(c.includeSkins!==false&&c.includeChromas!==false&&allowed(x,null)&&(qs.length||other.some(m=>m.chromaId!=null))?row('Base',other,'chroma',''):'')+cr}).join('');
 const unknown=ms.filter(m=>!matched.has(m));
 return `<details class="challenge-champion${completed?' challenge-done':''}"><summary><img loading="lazy" src="${esc(basePortrait(ch))}" data-portrait="${esc(ch.iconUrl)}" alt=""><strong>${esc(name(ch))}</strong>${completed?'<span class="challenge-done-mark" title="Champion completed" aria-label="Champion completed">✓</span>':''}<span class="ct-progress">${esc(progress||`${ms.length} games`)}</span></summary><div class="challenge-children"><div class="ct-scroll"><table class="ct-table" style="min-width:${245+fields.length*112}px"><colgroup><col style="width:245px">${fields.map(()=>'<col style="width:112px">').join('')}</colgroup><thead><tr><th scope="col">${c.includeSkins===false?(c.includeChromas===false?'Champion':'Chroma'):(c.includeChromas===false?'Skin':'Skin / Chroma')}</th>${fields.map(k=>`<th scope="col">${esc(metrics[k])}</th>`).join('')}</tr></thead><tbody>${row('Total',ms,'total','')}${c.includeSkins===false&&c.includeChromas===false?'':skinRows}${c.includeSkins!==false&&unknown.length?row('Unknown Skin',unknown,'skin',''):''}</tbody></table></div><div class="ct-sticky-scroll" hidden><input type="range" min="0" max="0" value="0" step="1" aria-label="Scroll statistics horizontally"></div></div></details>`
}
const challengeTypes={endless:'Endless',streak:'Win Streak',rounds:'Multi-round'};
const entryOwner=(k,owners)=>k.startsWith('champ:')?Number(k.split(':')[1]):Number(owners.get(k.split(':')[0]));
const matchKey=(c,m)=>c.includeSkins===false&&c.includeChromas===false?`champ:${m.championId}`:`${m.skinId}:${c.includeChromas===false?'base':m.chromaId??'base'}`;
function challengeEntries(c){if(c.includeSkins===false&&c.includeChromas===false)return c.champions.map(i=>`champ:${i}`);const entries=[];for(const x of D.skins){if(x.isTFT===true||!c.champions.map(Number).includes(x.championId)||(c.skins.length&&!c.skins.map(Number).includes(x.id)))continue;const qs=D.chromas.filter(q=>q.skinId===x.id&&q.isTFT!==true);if(c.includeSkins!==false&&!c.chromas.length)entries.push(`${x.id}:base`);if(c.includeChromas!==false)for(const q of qs)if(!c.chromas.length||c.chromas.map(Number).includes(q.id))entries.push(`${x.id}:${q.id}`);}return [...new Set(entries)];}
function challengeRun(c,ms){const entries=c.runEntries??challengeEntries(c), type=c.type||'endless';let active=new Set(entries), played=new Map(), round=1, ignored=0, streak=null;const accepted=[], rounds=[{entries:new Set(active),matches:[]}];if(type==='endless')return {accepted:ms.filter(m=>eligible(m,c)),active,round,played,ignored};for(const m of ms){const k=matchKey(c,m);if(!eligible(m,c)||!active.has(k)||typeof m.win!=='boolean'||(type==='rounds'&&played.has(k))||(type==='streak'&&streak!==null&&streak!==k)){ignored++;continue;}accepted.push(m);rounds.at(-1).matches.push(m);if(type==='streak'){streak=m.win?k:null;if(!m.win)active.delete(k);}else{played.set(k,m.win);if(played.size===active.size){active=new Set([...played].filter(([,w])=>w).map(([k])=>k));played=new Map();if(active.size){round++;rounds.push({entries:new Set(active),matches:[]});}}}}return {accepted,active,round,played,ignored,streak,rounds};}
function runSummary(c,r){if(!c.type||c.type==='endless')return '<p class="muted">Endless</p>';const n=(c.runEntries??challengeEntries(c)).length;return `<p><strong>${challengeTypes[c.type]}${c.type==='rounds'?` · Round ${r.round}`:''}</strong> · ${n===0?'No eligible combinations':r.active.size?'In progress':'Completed'} · ${r.active.size} remaining${c.type==='rounds'?` · ${r.played.size}/${r.active.size} played this round`:''}${r.ignored?` · ${r.ignored} assigned games outside the rules (excluded)`:''}</p>`;}
const roundViews={}, archiveView={}, expandedChallenges=new Set();
function rememberChallengeExpansion(){for(const el of V.querySelectorAll('details[data-challenge-panel]')){if(el.open)expandedChallenges.add(el.dataset.challengePanel);else expandedChallenges.delete(el.dataset.challengePanel);}}
function getRun(c){return challengeRun(c,(c.archivedMatches??S.matches.filter(m=>assigned(m,c)&&(!(c.modes??[]).length||c.modes.includes(m.mode))&&(!c.start||String(m.date).slice(0,10)>=c.start))).slice().sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''))));}
function challengeRows(c,ms,fields,entries=null,run=null,total=false){let ids=new Set([...c.champions.map(Number),...ms.map(m=>Number(m.championId))]);const skinIds=new Map(D.skins.map(x=>[String(x.id),x.championId]));const belongs=(k,id)=>entryOwner(k,skinIds)===id;const completedIds=new Set(run?overviewData(c,run).filter(x=>x.done).map(x=>x.id):[]);return [...ids].map(champ).filter(Boolean).filter(ch=>!entries||[...entries].some(k=>belongs(k,ch.id))).sort((a,b)=>(S.mastery[b.id]?.level??-1)-(S.mastery[a.id]?.level??-1)||name(a).localeCompare(name(b))).map(ch=>{const m=ms.filter(m=>Number(m.championId)===ch.id);let progress=`${m.length} games`;if(entries&&!total){const keys=[...entries].filter(k=>belongs(k,ch.id));const done=c.type==='streak'?keys.filter(k=>!run.active.has(k)).length:new Set(m.map(x=>matchKey(c,x))).size;progress=`${done} / ${keys.length}`;}return challengeChampion(c,ch,m,fields,entries,progress,completedIds.has(ch.id))}).join('');}
const overviewViews=new Set();
function overviewData(c,r){const owners=new Map(D.skins.map(x=>[String(x.id),Number(x.championId)])), byId=new Map();const ids=c.champions.map(Number);for(const id of ids)byId.set(id,{id,keys:[],games:0,rounds:[],done:false});for(const k of (c.runEntries??challengeEntries(c))){const row=byId.get(entryOwner(k,owners));if(row)row.keys.push(k);}for(const m of r.accepted){const row=byId.get(Number(m.championId));if(row)row.games++;}for(const row of byId.values()){const type=c.type||'endless';row.done=type!=='endless'&&row.keys.length>0&&!row.keys.some(k=>r.active.has(k));row.completed=row.keys.filter(k=>!r.active.has(k)).length;if(type==='rounds')row.rounds=r.rounds.map((rd,i)=>({number:i+1,total:[...rd.entries].filter(k=>entryOwner(k,owners)===row.id).length,played:rd.matches.filter(m=>Number(m.championId)===row.id).length})).filter(x=>x.total>0);}return [...byId.values()].filter(x=>champ(x.id)).sort((a,b)=>name(champ(a.id)).localeCompare(name(champ(b.id))));}
function challengeOverview(c,r){const type=c.type||'endless', rows=overviewData(c,r), done=rows.filter(x=>x.done).length;return `<section class="co-section"><div class="co-heading"><div><h3>Challenge Overview</h3></div><div class="co-summary">${type==='endless'?`${rows.length} Champions`:`${done} / ${rows.length} Champions Completed`}</div></div><div class="co-grid">${rows.map(x=>{const ch=champ(x.id);return `<article class="co-card co-${type} ${x.done?'co-done':''}"><div class="co-champion"><img loading="lazy" src="${esc(basePortrait(ch))}" data-portrait="${esc(ch.iconUrl)}" alt=""><strong>${esc(name(ch))}</strong>${x.done?'<span class="co-check" title="Champion completed" aria-label="Champion completed">✓</span>':''}</div>${type==='rounds'?`<div class="co-rounds">${x.rounds.map(rd=>`<div class="co-round ${rd.played===rd.total?'co-round-done':''}"><span>#${rd.number}</span><strong>${rd.played}/${rd.total}</strong></div>`).join('')||'<small class="muted">No eligible entries</small>'}</div>`:`<div class="co-value">${x.games}${type==='streak'?`<span>/${x.keys.length}</span>`:''}</div>${type==='streak'?`<div class="co-track" role="progressbar" aria-label="Completed combinations" aria-valuenow="${x.completed}" aria-valuemax="${x.keys.length||1}"><i style="width:${x.keys.length?100*x.completed/x.keys.length:0}%"></i></div>`:''}`}</article>`}).join('')}</div></section>`;}
function challengePanel(raw){const c=normalizeChallenge(raw),r=getRun(c),fields=c.metrics.filter(k=>metrics[k]),multi=c.type==='rounds',choice=roundViews[c.id]??'Total',selected=multi&&choice!=='Total'?r.rounds[Number(choice)-1]:null,ms=selected?selected.matches:r.accepted,entries=selected?selected.entries:c.type==='streak'?new Set(c.runEntries??challengeEntries(c)):multi?new Set(c.runEntries??challengeEntries(c)):null,finished=c.type==='endless'||((c.runEntries??challengeEntries(c)).length>0&&!r.active.size);return `<details class="panel challenge-panel" data-challenge-panel="${esc(c.id)}" ${expandedChallenges.has(String(c.id))?'open':''}><summary><strong>${esc(c.name)}</strong> <span class="muted">${esc(challengeTypes[c.type]||'Endless')} · ${r.accepted.length} games</span></summary><p>${esc((c.modes??[]).join(', ')||'All modes')} · ${ms.length} games · Start Date: ${esc(c.start||'Not set')}</p>${runSummary(c,r)}<div class="tools co-toggle"><button data-overview-choice="${esc(c.id)}" class="${overviewViews.has(String(c.id))?'active':''}" aria-pressed="${overviewViews.has(String(c.id))}">Overview</button><button data-detail-choice="${esc(c.id)}" class="${!overviewViews.has(String(c.id))?'active':''}" aria-pressed="${!overviewViews.has(String(c.id))}">Details</button></div>${overviewViews.has(String(c.id))?challengeOverview(c,r):`${multi?`<div class="tools">${['Total',...r.rounds.map((_,i)=>String(i+1))].map(v=>`<button data-round-choice="${v}" data-cid="${esc(c.id)}" class="${choice===v?'active':''}">${v==='Total'?v:'Round '+v}</button>`).join('')}</div>`:''}${challengeRows(c,ms,fields,entries,r,multi&&!selected)}`}<div class="tools">${raw.deleted?`<button data-restorechallenge="${esc(c.id)}">Restore</button> <button data-purgechallenge="${esc(c.id)}">Delete Permanently</button>`:!c.archived?`<button data-edit="${esc(c.id)}">Edit</button>${finished?` <button data-archive="${esc(c.id)}">Archive</button> <button data-addstats="${esc(c.id)}">${c.addedToStatistics?'Added to Statistics':'Add to Statistics'}</button>`:''}`:`<button data-addstats="${esc(c.id)}">${c.addedToStatistics?'Added to Statistics':'Add to Statistics'}</button>`} ${raw.deleted?'':`<button data-delchallenge="${esc(c.id)}">Delete</button>`}</div></details>`;}
function challenges(){rememberChallengeExpansion();const active=S.challenges.filter(c=>!c.archived&&!c.deleted),archived=S.challenges.filter(c=>c.archived&&!c.deleted);V.innerHTML='<h2>My Challenges</h2><button data-go="Challenge Creator">New Challenge</button>'+(active.map(challengePanel).join('')||'<p class="empty-state">No active challenges yet.</p>')+'<h2>Archived Challenges</h2>'+(archived.map(challengePanel).join('')||'<p class="empty-state">No archived challenges yet.</p>')+'<h2>Statistics</h2>'+statisticsPanel();}
function deletedChallenges(){rememberChallengeExpansion();const deleted=S.challenges.filter(c=>c.deleted);V.innerHTML='<h2>Deleted Challenges</h2>'+(deleted.map(challengePanel).join('')||'<p class="empty-state">No deleted challenges yet.</p>');}
function statisticsPanel(){const added=S.challenges.filter(c=>c.addedToStatistics);if(!added.length)return '<p class="empty-state">No challenges added to statistics yet.</p>';const fields=[...new Set(added.flatMap(c=>normalizeChallenge(c).metrics))],matches=new Map(),ids=new Set();for(const raw of added){const c=normalizeChallenge(raw);c.champions.forEach(id=>ids.add(id));for(const m of raw.statisticMatches??getRun(c).accepted){if(!matches.has(m.id))matches.set(m.id,m);}}const ms=[...matches.values()],c={champions:[...ids],skins:[],chromas:[],metrics:fields,type:'endless'};return `<p>${added.length} challenges · ${ms.length} unique games</p>${challengeRows(c,ms,fields)}`;}
V.addEventListener('click',e=>{const d=e.target.closest('button')?.dataset;if(!d)return;if(d.overviewChoice||d.detailChoice){if(d.overviewChoice)overviewViews.add(d.overviewChoice);else overviewViews.delete(d.detailChoice);render();return;}if(d.roundChoice){roundViews[d.cid]=d.roundChoice;render();}if(d.archive||d.addstats){const raw=S.challenges.find(c=>c.id===(d.archive||d.addstats));if(!raw)return;const c=normalizeChallenge(raw),r=getRun(c);if(d.archive){raw.archivedMatches=structuredClone(r.accepted);raw.archived=true;}else if(!raw.addedToStatistics){raw.statisticMatches=structuredClone(r.accepted);raw.addedToStatistics=true;}save();challenges();}});



function matches(){V.innerHTML=`<h2>Match History</h2><div class="compact-matches">${S.matches.slice().reverse().map(m=>{const c=champ(m.championId);return `<details class="compact-match"><summary><img src="${esc(c?basePortrait(c):'')}" alt=""><span class="match-caption"><strong>${esc(c?.name??'Unknown champion')}</strong><small>${esc(m.mode)}</small></span><span class="match-kda">${[m.kills,m.deaths,m.assists].map(x=>esc(x??'—')).join(' / ')}</span><span class="match-chevron" aria-hidden="true">›</span></summary><div class="compact-match-body">${matchAssignment(m)}<button type="button" data-delmatch="${esc(m.id)}">Delete Match</button></div></details>`}).join('')||'<p class="muted">No matches recorded yet.</p>'}</div>`}

function rank(){V.innerHTML=`<h2>Ranked Progress</h2><form id="rankform" class="fields"><label>Date<input name="date" type="date" required value="${new Date().toISOString().slice(0,10)}"></label><label>Queue<select name="queue"><option>Ranked Solo/Duo</option><option>Ranked Flex</option></select></label><label>Rank<input name="tier" required placeholder="Gold II"></label><label>LP<input name="lp" type="number" min="0" required></label><button>Save Snapshot</button></form><div class="table"><table><tr><th>Date</th><th>Queue</th><th>Rank</th><th>LP</th></tr>${S.rank.slice().reverse().map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.queue)}</td><td>${esc(x.tier)}</td><td>${x.lp}</td></tr>`).join('')}</table></div>`}
function backup(){V.innerHTML='<h2>Backup & Restore</h2><p>Export all League of Legends progress. Import replaces only League of Legends data, never Guild Wars 2.</p><button id="export">Export JSON</button> <input type="file" accept=".json" id="import">'}
V.addEventListener('input',e=>{let t=e.target;if(t.id==='search'){query=t.value;cp=0;catalog();let n=$('#search');n.focus();n.setSelectionRange(query.length,query.length)}if(draft&&page==='Challenge Creator'){let k={dn:'name',dg:'goal',dm:'goalMetric',ds:'scope',dq:'mode',dt:'start'}[t.id];if(k)draft[k]=k==='goal'?Number(t.value):t.value}});
V.addEventListener('change',async e=>{let t=e.target,d=t.dataset;if(t.id==='championSort'){championSort=t.value;championOverview();return}if(t.id==='portraitChampion'){portraitChampion=Number(t.value);settings();return}if(t.id==='filter'){filter=t.value;cp=0;catalog()}if(d.own!==undefined){S.owned[cat+':'+d.own]=t.checked;save()}if(d.mastery){let [i,k]=d.mastery.split(':');(S.mastery[i]||={})[k]=Math.max(0,Number(t.value)||0);save()}if(d.eternal){S.eternals[d.eternal]=Math.max(0,Number(t.value)||0);save()}if(t.id==='challengeType'){draft.type=t.value}if(d.inclusion){draft[d.inclusion]=t.checked;if(!t.checked)draft[d.inclusion==='includeSkins'?'skins':'chromas']=[]}if(d.mode){draft.modes=t.checked?[...draft.modes,d.mode]:draft.modes.filter(x=>x!==d.mode)}if(d.metric){const keys=progressBundles[d.metric]??[d.metric];draft.metrics=t.checked?[...new Set([...draft.metrics,...keys])]:draft.metrics.filter(x=>!keys.includes(x))}if(d.pick){let [k,i]=d.pick.split(':');i=Number(i);draft[k]=t.checked?[...draft[k],i]:draft[k].filter(x=>x!==i);if(k==='champions'){draft.skins=draft.skins.filter(i=>draft.champions.includes(D.skins.find(x=>x.id===i)?.championId));draft.chromas=draft.chromas.filter(i=>draft.champions.includes(D.chromas.find(x=>x.id===i)?.championId));creator()}}if(t.id==='mc'){ $('#ms').innerHTML='<option value="">Unknown</option>'+D.skins.filter(x=>x.championId===Number(t.value)).map(x=>`<option value="${x.id}">${esc(name(x))}</option>`).join('');$('#mch').innerHTML='<option value="">None / Unknown</option>'}if(t.id==='ms')$('#mch').innerHTML='<option value="">None / Unknown</option>'+D.chromas.filter(x=>x.skinId===Number(t.value)).map(x=>`<option value="${x.id}">${esc(name(x))}</option>`).join('');if(t.id==='import'){if(demoMode){t.value='';status.textContent='Exit Demo Mode before importing a backup.';return}try{let a=JSON.parse(await t.files[0].text());if(a.version!==1||!['owned','mastery','eternals'].every(k=>a[k]&&typeof a[k]==='object'&&!Array.isArray(a[k]))||!['matches','challenges','rank'].every(k=>Array.isArray(a[k])))throw Error('Invalid backup');if(confirm('Replace current LoL progress?')){S=a;save();render()}}catch(e){status.textContent='Import failed: '+e.message}}});
document.addEventListener('click',e=>{let t=e.target.closest('button');if(!t)return;let d=t.dataset;if(page==='Settings'&&(d.portraitChampion!==undefined||t.id==='portraitBack')){portraitChampion=t.id==='portraitBack'?null:Number(d.portraitChampion);settings();return}if(page==='Settings'&&(d.portraitSkin!==undefined||t.id==='resetPortrait')){const c=champ(portraitChampion);if(!c)return;const skin=portraitSkins(c).find(x=>String(x.id)===d.portraitSkin);if(t.id!=='resetPortrait'&&!skin)return;if(!S.portraits||typeof S.portraits!=='object'||Array.isArray(S.portraits))S.portraits={};if(!skin||skin.isBase)delete S.portraits[c.id];else S.portraits[c.id]=skin.id;save();settings();return}if(d.go){if(d.go==='Settings')portraitChampion=null;if(d.go==='Challenge Creator')step=0;go(d.go)}if(d.wizard!==undefined){if(Number(d.wizard)>0&&!draft.modes.length){step=0;creator();creatorError('Select at least one game mode.');return}step=Number(d.wizard);creator()}if(d.lane){lane=d.lane;creator()}if(d.selectmetrics){draft.metrics=d.selectmetrics==='all'?Object.keys(metrics):[];creator()}if(d.cat){cat=d.cat;cp=0;query='';filter='All';catalog()}if(d.step){cp+=Number(d.step);catalog()}if(t.id==='allch'||t.id==='nonech'){draft.champions=t.id==='allch'?regular().map(x=>x.id):[];if(!draft.champions.length){draft.skins=[];draft.chromas=[]}creator()}if(demoMode&&t.id==='testchallenge'){let a=newDraft();a.name='Test Challenge';a.start=localDate();a.modes=[modes[0]];a.champions=regular().filter(c=>['Ahri','Lulu','Nami'].includes(c.name)).map(c=>c.id);if(!a.champions.length)a.champions=regular().slice(0,3).map(c=>c.id);a.metrics=['games','wins','losses','winrate','firstBlood','cc','shielding','longestAlive'];S.challenges.push(a);save();render()}if(t.id==='savechallenge'){let a=draft;if(!a.name.trim()||!a.modes.length||!a.champions.length||!a.metrics.length){step=!a.name.trim()||!a.modes.length?0:!a.champions.length?1:2;creator();creatorError(!a.name.trim()?'Enter a challenge name.':!a.modes.length?'Select at least one game mode.':!a.champions.length?'Select at least one champion.':'Select at least one statistic.');return}a.start=validStart(a.start)?a.start:localDate();a.scope='champion';a.mode='All';if(a.type&&a.type!=='endless'){a.runEntries=challengeEntries(a);if(!a.runEntries.length){creatorError('No eligible skin or chroma combinations. Check your collection tracking options and filters.');return}}else delete a.runEntries;S.challenges=S.challenges.filter(x=>x.id!==a.id);S.challenges.push(a);draft=null;save();go('My Challenges')}if(t.id==='cancelchallenge'){draft=null;go('My Challenges')}if(d.edit){draft=normalizeChallenge(structuredClone(S.challenges.find(x=>x.id===d.edit)));step=0;go('Challenge Creator')}if(d.delchallenge){const q=S.challenges.find(x=>x.id===d.delchallenge);if(q){q.deleted=true;save();render()}}if(d.restorechallenge){const q=S.challenges.find(x=>x.id===d.restorechallenge);if(q){delete q.deleted;save();render()}}if(d.purgechallenge){const q=S.challenges.find(x=>String(x.id)===d.purgechallenge&&x.deleted);if(q&&confirm('Permanently delete this challenge? Its challenge statistics will be removed, but match history will be kept. This cannot be undone.')){const id=String(q.id);for(const m of S.matches){const prior=assignment(m);if(prior===id||(!Object.hasOwn(m,'challengeId')&&(Array.isArray(m.challengeIds)?m.challengeIds.map(String).includes(id):eligible(m,q)))){m.challengeId=prior===id?null:prior;delete m.challengeIds;}}S.challenges=S.challenges.filter(x=>String(x.id)!==id);expandedChallenges.delete(id);overviewViews.delete(id);delete roundViews[id];V.querySelectorAll('details[data-challenge-panel]').forEach(el=>{if(el.dataset.challengePanel===id)el.remove()});save();render()}}if(d.delmatch&&confirm('Delete match?')){S.matches=S.matches.filter(x=>x.id!==d.delmatch);save();render()}if(t.id==='export'){if(demoMode){status.textContent='Exit Demo Mode before exporting your real backup.';return}let u=URL.createObjectURL(new Blob([JSON.stringify(S,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=u;a.download='chairmode-lol-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}});
V.addEventListener('submit',e=>{e.preventDefault();let a=Object.fromEntries(new FormData(e.target));if(e.target.id==='matchform'){for(let k of [...numeric,'masteryGained','masteryLevelGained','eternalsGained','championId','skinId','chromaId'])a[k]=a[k]===''?null:Number(a[k]);a.firstBloodCombined=true;a.win=a.win==='true';a.id=crypto.randomUUID();a.challengeId=null;S.matches.push(a)}else if(e.target.id==='rankform'){a.lp=Number(a.lp);S.rank.push(a)}else return;save();render()});

const eligible=(m,c)=>{c=normalizeChallenge(c);const modes=c.modes??(c.mode==='All'||!c.mode?[]:[c.mode]);return (!c.champions.length||c.champions.map(Number).includes(Number(m.championId)))&&(c.includeSkins===false||!c.skins.length||c.skins.includes(m.skinId))&&(c.includeChromas===false||!c.chromas.length||c.chromas.includes(m.chromaId))&&(!(c.includeSkins===false&&c.includeChromas!==false)||m.chromaId!=null)&&(!modes.length||modes.includes(m.mode))&&(!c.start||m.date>=c.start)};
const assignment=m=>{if(Object.hasOwn(m,'challengeId'))return m.challengeId==null?null:String(m.challengeId);const ids=Array.isArray(m.challengeIds)?m.challengeIds.map(String):S.challenges.filter(c=>eligible(m,c)).map(c=>String(c.id));return ids.length===1?ids[0]:null};
const assigned=(m,c)=>assignment(m)===String(c.id);
const progression=['mastery','masteryLevel','eternals'];
const validNumber=v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v))&&Number(v)>=0;
const matchGain=(m,p)=>validNumber(m[p+'Gained'])?Number(m[p+'Gained']):validNumber(m[p+'Start'])&&validNumber(m[p+'End'])&&Number(m[p+'End'])>=Number(m[p+'Start'])?Number(m[p+'End'])-Number(m[p+'Start']):null;
const eternalEntries=m=>Object.entries(m.eternalGains||{}).filter(([,v])=>validNumber(v));
const progressionEditor=m=>`<details><summary>Match Progression</summary>${progression.map(p=>`<label>${metrics[p+'Gained']}<input type="number" min="0" step="1" data-gain="${p}" value="${esc(matchGain(m,p)??'')}" placeholder="Unknown"></label>`).join('')}<details><summary>Individual Eternals</summary>${D.eternals.filter(x=>x.championId===Number(m.championId)&&x.isTFT!==true).map(x=>`<label>${esc(name(x))}<input type="number" min="0" step="1" data-eternal-gain="${esc(id('eternals',x))}" value="${esc(m.eternalGains?.[id('eternals',x)]??'')}" placeholder="Unknown"></label>`).join('')}</details><small>Enter gains from this match only. Blank = unknown. Individual Eternals are recorded separately from the total.</small></details>`;
const challengeMatches=ms=>{const seen=new Set();return ms.filter(m=>{if(seen.has(String(m.id))||!S.challenges.some(c=>assigned(m,c)))return false;seen.add(String(m.id));return true})};
let profileId=null;
const collectionTile=(t,x,c)=>`<button type="button" class="collection-item ${own(t,x)?'collected':''}" data-collection="${t}:${esc(id(t,x))}" aria-pressed="${own(t,x)}"><img loading="lazy" src="${esc(t==='skins'?skinPortrait(c,x):x.imageUrl||asset(x.chromaPath))}" alt=""><span>${esc(t==='skins'?skinLabel(x,c):chromaLabel(x,D.skins.find(s=>s.id===x.skinId)))}</span></button>`;
const fold=(title,content)=>`<details class="profile-fold"><summary>${esc(title)}</summary><div class="fold-body">${content}</div></details>`;
function profile(c){
 const skins=portraitSkins(c), chromas=D.chromas.filter(x=>x.championId===c.id&&x.isTFT!==true), es=D.eternals.filter(x=>x.championId===c.id&&x.isTFT!==true), m=S.mastery[c.id]||{}, ms=challengeMatches(S.matches.filter(x=>Number(x.championId)===c.id)), a=stats(ms), selected=skins.find(x=>String(x.id)===String(S.portraits?.[c.id]))||skins.find(x=>x.isBase), counts=xs=>xs.length?xs.length:0;
 const cards=keys=>`<div class="profile-stats">${keys.map(k=>`<div><small>${esc(metrics[k])}</small><strong>${esc(display(k,a[k]))}</strong></div>`).join('')}</div>`;
 const total=es.filter(x=>S.eternals[id('eternals',x)]!=null);const et=total.length?fmt(total.reduce((n,x)=>n+Number(S.eternals[id('eternals',x)]),0)):'—';
 V.innerHTML=`<button id="profileBack">← All champions</button><div class="profile-banner" style="background-image:linear-gradient(0deg,#101522,transparent),url('${esc(selected?.splashUrl||asset(selected?.splashPath)||basePortrait(c))}')"><h2>${esc(name(c))}</h2></div><div class="profile-stats">${[['Mastery Points',fmt(m.points)],['Mastery Level',fmt(m.level)],['Eternals',et],['Challenge Games',ms.length]].map(([k,v])=>`<div><small>${k}</small><strong>${esc(v)}</strong></div>`).join('')}</div>`+
 `<div class="profile-columns"><div class="profile-main">`+
 fold('Skins',`<p class="muted">Click a skin to mark or unmark it as collected.</p><div class="collection-grid">${skins.filter(x=>!x.isBase).map(x=>collectionTile('skins',x,c)).join('')}</div>`)+
 fold('Chromas',skins.map(x=>{const list=chromas.filter(q=>q.skinId===x.id);return list.length?`<h3>${esc(skinLabel(x,c))}</h3><div class="collection-grid">${list.map(q=>collectionTile('chromas',q,c)).join('')}</div>`:''}).join('')||'<p>No chromas listed.</p>')+
 fold('Active Challenges',S.challenges.filter(raw=>{if(raw.deleted||raw.archived)return false;const q=normalizeChallenge(raw);return !q.champions.length||q.champions.map(Number).includes(c.id)}).map(q=>`<div class="eternal-row"><strong>${esc(q.name)}</strong><span>${ms.filter(m=>assigned(m,q)).length} games</span></div>`).join('')||'<p>No active challenges.</p>')+
 fold('Challenge Statistics',cards(['games','wins','losses','duration','kills','deaths','assists','kda','masteryGained','masteryLevelGained','eternalsGained']))+fold('Multikill Tracker',cards(['double','triple','quadra','penta']))+
 `</div><aside class="profile-side"><h3>Combat Records</h3><p class="muted">Challenge games only</p>${[['kills','Kills'],['firstBlood','First Bloods'],['kp','Kill Participation'],['spree','Largest Killing Spree'],['longestAlive','Time Alive']].map(([k,label])=>`<div class="profile-side-stat"><small>${esc(label)}</small><strong>${esc(display(k,a[k]))}</strong></div>`).join('')}</aside></div>`;
}
function matchAssignment(m){const c=champ(m.championId);if(!c)return '';const skins=portraitSkins(c), chromas=D.chromas.filter(x=>x.skinId===Number(m.skinId)&&x.championId===c.id&&x.isTFT!==true);const opts=(xs,v,parent)=>xs.map(x=>`<option value="${x.id}" ${String(v)===String(x.id)?'selected':''}>${esc(parent?chromaLabel(x,parent):skinLabel(x,c))}</option>`).join('');return `<div class="match-assignment" data-match="${esc(m.id)}"><label>Skin<select data-match-field="skinId"><option value="">Unknown</option>${opts(skins,m.skinId)}</select></label><label>Chroma<select data-match-field="chromaId"><option value="">None / Unknown</option>${opts(chromas,m.chromaId,skins.find(x=>x.id===Number(m.skinId)))}</select></label><label>Assigned Challenge<select data-match-challenge><option value="">None</option>${S.challenges.filter(q=>(!q.deleted&&!q.archived&&eligible(m,q))||assigned(m,q)).map(q=>`<option value="${esc(q.id)}" ${assigned(m,q)?'selected':''}>${esc(q.name)}</option>`).join('')}</select></label>${!Object.hasOwn(m,'challengeId')&&((Array.isArray(m.challengeIds)?m.challengeIds.length:S.challenges.filter(q=>eligible(m,q)).length)>1)?'<small>Previous multiple assignments: choose one challenge.</small>':''}${progressionEditor(m).replace('<summary>Match Progression</summary>','<summary>Advanced Progression (manual)</summary>')}</div>`}

V.addEventListener('click',e=>{const card=e.target.closest('[data-profile]');if(card){profileId=Number(card.dataset.profile);championOverview();window.scrollTo(0,0);return}if(e.target.closest('#profileBack')){profileId=null;championOverview();return}const b=e.target.closest('[data-collection]');if(b){const k=b.dataset.collection;S.owned[k]=!S.owned[k];b.classList.toggle('collected',S.owned[k]);b.setAttribute('aria-pressed',String(S.owned[k]));save()}});
V.addEventListener('keydown',e=>{if(e.target.matches('[data-profile]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.click()}});
V.addEventListener('change',e=>{const t=e.target,wrap=t.closest('[data-match]');if(!wrap)return;const m=S.matches.find(x=>String(x.id)===wrap.dataset.match);if(!m)return;if(t.dataset.matchField){m[t.dataset.matchField]=t.value?Number(t.value):null;if(t.dataset.matchField==='skinId')m.chromaId=null;save();wrap.outerHTML=matchAssignment(m)}else if(t.dataset.matchChallenge!==undefined){m.challengeId=t.value||null;save()}else if(t.dataset.gain!==undefined||t.dataset.eternalGain!==undefined){if(t.value!==''&&(!validNumber(t.value)||!Number.isInteger(Number(t.value)))){t.reportValidity();return}if(t.dataset.gain!==undefined){m[t.dataset.gain+'Gained']=t.value===''?null:Number(t.value);if(t.value===''){m[t.dataset.gain+'Start']=null;m[t.dataset.gain+'End']=null}}else{m.eternalGains??={};if(t.value==='')delete m.eternalGains[t.dataset.eternalGain];else m.eternalGains[t.dataset.eternalGain]=Number(t.value)}save();const row=wrap.closest('tr');const keys=Object.keys(metrics).filter(k=>!['games','wins','losses','winrate','kills','deaths','assists'].includes(k));const a=stats([m]);keys.forEach((k,i)=>{if(row?.cells[i+5])row.cells[i+5].textContent=display(k,a[k])})}});
(async()=>{try{for(const t of ['champions','skins','chromas','eternals','emotes','icons','titles','skinlines']){let r=await fetch('data/'+t+'.json');if(!r.ok)throw Error(t+' unavailable');let a=await r.json();D[t]=t==='eternals'?a.entries:a;if(!Array.isArray(D[t]))throw Error('Invalid '+t)}status.textContent='Catalogues loaded · Manual tracking mode';render()}catch(e){status.textContent='Loading failed: '+e.message+' — open via GitHub Pages, not file://.'}})();

// Keep the horizontal control available while scrolling through long champion tables.
function syncChallengeScroll(sc){
 const bar=sc.nextElementSibling;if(!bar?.classList.contains('ct-sticky-scroll'))return;
 const input=bar.querySelector('input'),max=Math.max(0,sc.scrollWidth-sc.clientWidth);
 bar.hidden=max===0;input.max=String(max);input.value=String(Math.round(sc.scrollLeft));
}
V.addEventListener('toggle',e=>{if(e.target.matches('details.challenge-champion')&&e.target.open){const sc=e.target.querySelector('.ct-scroll');if(sc)requestAnimationFrame(()=>syncChallengeScroll(sc));}},true);
V.addEventListener('scroll',e=>{if(e.target.matches?.('.ct-scroll'))syncChallengeScroll(e.target);},true);
V.addEventListener('input',e=>{if(e.target.matches('.ct-sticky-scroll input')){const sc=e.target.parentElement.previousElementSibling;sc.scrollLeft=Number(e.target.value);}});
window.addEventListener('resize',()=>V.querySelectorAll('.challenge-champion[open] .ct-scroll').forEach(syncChallengeScroll));

function makeDemo(){
 const out=empty(), all=regular().filter(c=>!c.isTFT), picks=['Ahri','Akali','Ashe','Jinx','Lulu','Lux','Nami','Garen','Ezreal','Katarina','Sona','Thresh'].map(n=>all.find(c=>c.name===n)).filter(Boolean);
 let seq=0;const totals={};
 for(const [i,c] of picks.entries()) {const sk=portraitSkins(c), non=sk.filter(x=>!x.isBase);out.mastery[c.id]={level:7+i,points:24000+i*18230};if(non.length)out.portraits[c.id]=non[i%non.length].id;sk.filter((_,j)=>j%3!==2).forEach(x=>out.owned['skins:'+x.id]=true);D.chromas.filter(x=>x.championId===c.id&&!x.isTFT).filter((_,j)=>j%4===0).forEach(x=>out.owned['chromas:'+x.id]=true);D.eternals.filter(x=>x.championId===c.id&&!x.isTFT).forEach((x,j)=>{out.owned['eternals:'+id('eternals',x)]=true;out.eternals[id('eternals',x)]=12+i*20+j*8});}
 function make(label,type,cs,count){let c={...newDraft(),id:'demo-'+label.toLowerCase().replace(/[^a-z]+/g,'-'),name:label,type,start:'2026-01-01',champions:cs.map(x=>x.id),metrics:Object.keys(metrics),modes:['Ranked Solo/Duo','Normal Draft']};let keys=[];for(const ch of cs){const sk=portraitSkins(ch);let opts=[];for(const x of sk){opts.push(x.id+':base');for(const q of D.chromas.filter(q=>q.skinId===x.id&&!q.isTFT).slice(0,2))opts.push(x.id+':'+q.id)}keys.push(...opts.slice(0,count));}c.runEntries=keys;out.challenges.push(c);return c;}
 function add(c,k,win){const [sid,qid]=k.split(':'),skin=D.skins.find(x=>x.id===Number(sid));if(!skin)return;const i=++seq, cid=skin.championId, t=totals[cid]??={p:10000,l:5,e:100};const m={id:'demo-match-'+i,challengeId:c.id,championId:cid,skinId:Number(sid),chromaId:qid==='base'?null:Number(qid),win,date:new Date(Date.UTC(2026,0,2,0,i*40)).toISOString(),mode:'Ranked Solo/Duo',rank:'Gold II',firstBloodCombined:true};for(const key of numeric)m[key]=i%7+1;Object.assign(m,{duration:24+i%18,kills:4+i%9,deaths:2+i%5,assists:5+i%12,damage:14000+i*317,taken:11000+i*211,mitigated:8000+i*90,objective:1500+i*40,turretDamage:1000+i*30,healing:2000+i*44,allyHealing:800+i*15,shielding:1500+i*22,vision:20+i%25,gold:10000+i*47,cs:120+i%90,kp:45+i%30,firstBlood:i%4===0?1:0,firstTowerTakedowns:i%3===0?1:0,longestAlive:300+i%400,spree:i%5+1,multikill:i%4+1,double:i%3,triple:i%5===0?1:0,quadra:i%13===0?1:0,penta:i%29===0?1:0,lp:win?24:-19,masteryStart:t.p,masteryEnd:t.p+650,masteryLevelStart:t.l,masteryLevelEnd:t.l+(i%9===0?1:0),eternalsStart:t.e,eternalsEnd:t.e+12}); t.p=m.masteryEnd;t.l=m.masteryLevelEnd;t.e=m.eternalsEnd;const es=D.eternals.filter(x=>x.championId===cid).slice(0,3);m.eternalGains=Object.fromEntries(es.map((x,j)=>[id('eternals',x),j+2]));out.matches.push(m);return m;}
 const a=make('Demo · Win Streak','streak',picks.slice(0,6),4);a.runEntries.slice(0,10).forEach((k,i)=>{if(i%2===0)add(a,k,true);add(a,k,false)});if(a.runEntries[10])add(a,a.runEntries[10],true);
 const b=make('Demo · Multi-round','rounds',picks.slice(0,6),5);let r=b.runEntries.filter((k,i)=>{let w=i%3!==0;add(b,k,w);return w});r=r.filter((k,i)=>{let w=i%2===0;add(b,k,w);return w});r.slice(0,Math.max(1,Math.floor(r.length/2))).forEach(k=>add(b,k,true));
 const e=make('Demo · Endless','endless',picks.slice(3,9),3);e.runEntries.forEach((k,i)=>add(e,k,i%3!==0));
 const f=make('Demo · Finished Challenge','streak',picks.slice(0,2),2);f.runEntries.forEach(k=>add(f,k,false));
 const ar=make('Demo · Archived Challenge','rounds',picks.slice(0,3),2);ar.runEntries.forEach(k=>add(ar,k,false));ar.archived=true;ar.addedToStatistics=true;ar.archivedMatches=structuredClone(out.matches.filter(m=>m.challengeId===ar.id));ar.statisticMatches=structuredClone(ar.archivedMatches);
 const st=make('Demo · Statistics Challenge','endless',picks.slice(0,3),2);st.runEntries.forEach(k=>add(st,k,true));st.archived=true;st.addedToStatistics=true;st.archivedMatches=structuredClone(out.matches.filter(m=>m.challengeId===st.id));st.statisticMatches=structuredClone(st.archivedMatches);
 const del=make('Demo · Deleted Challenge','streak',picks.slice(0,2),2);if(del.runEntries[0])add(del,del.runEntries[0],false);del.deleted=true;
 for(const [cid,t] of Object.entries(totals))out.mastery[cid]={level:t.l,points:t.p};return out;
}
